function routed($operation,$req){foreach($GLOBALS['routes']as $path=>$r){$match=match($operation){'create'=>$path==='/local-payments/topups','lookup'=>$path==='/local-payments/topups/lookup','summary'=>$path==='/wallet/summary','confirm'=>str_ends_with($path,'/confirm'),'cancel'=>str_ends_with($path,'/cancel'),'get'=>str_contains($path,'(?P<uuid>')&&!str_ends_with($path,'/confirm')&&!str_ends_with($path,'/cancel')};if($match)return ($r['callback'])($req);}throw new RuntimeException('missing route');}
$tests['every registered callback enforces auth role gate without rate writes']=function(){foreach(['create','confirm','cancel','get','lookup','summary']as $op){foreach(['unauthenticated','unsupported','gate','maintenance']as $mode){[$s,$p]=fixture($mode==='gate'?['local_dev_payments'=>false]:($mode==='maintenance'?['local_payment_maintenance'=>true]:[]));if($mode==='unauthenticated')$GLOBALS['owner']=0;if($mode==='unsupported')$GLOBALS['roles']=['subscriber'];$body=$op==='create'?'{"packId":"irt-10000","requestKey":"'.KEY.'"}':(in_array($op,['confirm','cancel'])?'{}':'');$query=$op==='lookup'?['requestKey'=>KEY]:[];$url=in_array($op,['confirm','cancel','get'])?['uuid'=>'aaaaaaaa-aaaa-4aaa-8aaa-000000000001']:[];$r=routed($op,request($body,$query,$url));eq($mode==='unauthenticated'?401:($mode==='unsupported'?403:503),$r->status,$op.' '.$mode);eq([],$p->writes);eq([],$p->rates);}}};
